// Author: MiYu. Original ability art, positions, hotkeys and levels drive learning and casting commands.
#include "session.h"
#include <algorithm>
#include <bit>
#include <sstream>

namespace war3 {
namespace {
float number(jass::Real v){return std::bit_cast<float>(v.bits());}
std::string levelText(const std::string& source,unsigned level){std::vector<std::string> values;std::string part;bool quote=false;for(auto c:source){if(c=='"'){quote=!quote;continue;}if(c==',' && !quote){values.push_back(part);part.clear();}else part+=c;}values.push_back(part);return values[std::min<size_t>(level?level-1:0,values.size()-1)];}
}
bool ScriptSession::canLearnSkill(std::uint32_t id,std::uint32_t ability) {if(!alive(id,NativeKind::Unit))return false;auto u=units_.at(id);if(!u->hero || u->morphed() || u->removing || u->paused || u->hidden() || number(u->life)<=0 || u->skillPoints<=0 || std::find(u->learnable.begin(),u->learnable.end(),ability)==u->learnable.end())return false;auto& data=definitions();int level=u->abilities.contains(ability)?u->abilities.at(ability):0;int skip=int(data.number(ability,"AbilityData","levelSkip"));if(!skip)skip=int(gameplayNumber("HeroAbilityLevelSkip",2));return level<int(data.number(ability,"AbilityData","levels",1)) && u->level>=int(data.number(ability,"AbilityData","reqLevel",1))+skip*level;}
std::vector<CommandButton> ScriptSession::abilityCommands(std::uint32_t id,unsigned player,bool learning) {
    std::vector<CommandButton> result;if(!alive(id,NativeKind::Unit))return result;auto u=units_.at(id);if(u->owner!=player || u->morphed() || u->construction || u->buildingUpgrade || u->unsummon)return result;auto& data=definitions();std::vector<std::uint32_t> abilities;if(learning)abilities=u->learnable;else for(auto [ability,level]:u->abilities)if(level>0 && (spellInfo(ability,unsigned(level)).kind!=SpellKind::Unsupported || passiveInfo(ability,unsigned(level)).kind!=PassiveKind::Unsupported || std::find(u->learnable.begin(),u->learnable.end(),ability)!=u->learnable.end()))abilities.push_back(ability);
    for(auto ability:abilities){
        unsigned level=u->abilities.contains(ability)?unsigned(std::max(0,u->abilities.at(ability))):0;unsigned shown=std::max(1u,std::min(learning?level+1:level,unsigned(std::max(1.f,data.number(ability,"AbilityData","levels",1)))));auto& s=spellInfo(ability,shown);auto& passive=passiveInfo(ability,shown);if(!learning && s.kind==SpellKind::Channel && !(s.channelOptions&1))continue;if(!learning && unitFormSpell(s.kind) && (s.formFlags&8) && alternateForm(*u,s))continue;
        bool reverse=!learning && unitFormSpell(s.kind) && s.unorder && !(s.formFlags&8) && s.kind!=SpellKind::Metamorphosis && alternateForm(*u,s);auto pos=data.field(ability,"Profile",learning?"Researchbuttonpos":reverse?"Unbuttonpos":"Buttonpos",data.field(ability,"Profile","Buttonpos"));auto comma=pos.find(',');if(comma==std::string::npos)continue;int x=std::stoi(pos.substr(0,comma)),y=std::stoi(pos.substr(comma+1));if(x<0 || x>3 || y<0 || y>2)throw std::runtime_error("Ability command position outside source console");
        auto source=[&](const char* field){return mapString(levelText(data.field(ability,"Profile",field),learning?level+1:level),strings_);};auto mana=reverse?0:s.mana;CommandButton b;b.action=learning?CommandAction::LearnSkill:passive.kind!=PassiveKind::Unsupported?CommandAction::PassiveSkill:CommandAction::CastSpell;b.type=ability;b.icon=source(learning?"ResearchArt":reverse?"Unart":"Art");b.name=source(learning?"Researchtip":reverse?"Untip":"Tip");b.tip=source(learning?"Researchubertip":reverse?"Unubertip":"Ubertip");b.hotkey=source(learning?"Researchhotkey":reverse?"Unhotkey":"Hotkey");if(b.name.empty())b.name=ObjectData::name(ability);b.x=x;b.y=y;if(!learning && !reverse && (s.formFlags&16)){b.gold=s.formGold;b.lumber=s.formLumber;auto& target=product(s.alternateType);if(b.name==ObjectData::name(ability))b.name=target.name;if(b.tip.empty())b.tip=target.tip;if(b.hotkey.empty())b.hotkey=target.hotkey;}if(!learning && s.orderOn && s.orderOff){bool active=u->autocast.contains(ability) && u->autocast.at(ability);if(!active && !s.offArt.empty())b.icon=s.offArt;b.tip+="|n"+source(active?"Unubertip":"Untip");}
        b.enabled=learning?canLearnSkill(id,ability):!u->paused && !u->stunned() && !u->hidden() && !u->removing && !u->illusion && number(u->life)>0 && number(u->mana)>=mana && ((reverse && s.kind!=SpellKind::StoneForm) || spellCooldown(id,ability)<=0);if(!learning && passive.kind!=PassiveKind::Unsupported){b.enabled=true;b.hotkey.clear();}b.reason=learning?"需要技能点或英雄等级":spellCooldown(id,ability)>0?"技能冷却中":number(u->mana)<mana?"魔法不足":"当前无法施法";
        if(!learning && (s.kind==SpellKind::Unload || s.kind==SpellKind::UnloadInstant || s.kind==SpellKind::StandDown || s.kind==SpellKind::UnloadCorpse) && !cargoCanUnload(*u)){b.enabled=false;b.reason="没有可卸载的乘员";}if(!learning && (s.kind==SpellKind::Load || s.kind==SpellKind::BattleStations || s.kind==SpellKind::LoadCorpse) && (!cargoReady(*u) || cargoUsed(id)>=cargoCapacity(id))){b.enabled=false;b.reason="货舱不可用或已满";}if(!learning && s.kind==SpellKind::Devour){auto hold=cargoInfo(*u);if(!cargoReady(*u) || !hold || hold->kind!=CargoKind::Devour || !u->cargo.empty()){b.enabled=false;b.reason=u->cargo.empty()?"吞噬货舱不可用":"正在消化单位";}}if(!learning && s.kind==SpellKind::ShadowMeld && ((s.nightOnly && requireWorld().clock().daytime()) || (u->shadowMeld && u->shadowMeld->remaining<=0))){b.enabled=false;b.reason=s.nightOnly && requireWorld().clock().daytime()?"只能在夜间隐藏":"已经处于隐藏状态";}if(b.action==CommandAction::CastSpell && u->cast && u->cast->phase==CastOrder::Phase::Channel && u->cast->spell.disableOthers && u->cast->spell.ability!=ability){b.enabled=false;b.reason="持续施法期间不可使用其他技能";}if(!learning && passive.kind==PassiveKind::Exhume){auto needs=s;needs.prerequisites=passive.prerequisites;if(!spellRequirements(player,needs)){b.enabled=false;b.reason="需要先满足科技条件";}}if(!learning && unitFormSpell(s.kind) && !unitFormReady(*u,s,false)){b.enabled=false;b.reason="当前形态无法转换";}if(!learning && !reverse && !spellRequirements(player,s)){b.enabled=false;b.reason="需要先满足科技条件";}if(s.kind==SpellKind::Unsupported && passive.kind==PassiveKind::Unsupported){b.enabled=false;b.reason="该技能效果尚未实现";}auto available=config_.players[player].abilityAvailable.find(ability);if(available!=config_.players[player].abilityAvailable.end() && !available->second){b.enabled=false;b.reason="技能已禁用";}result.push_back(std::move(b));
    }return result;
}
}
